            rule_section(:powers, "Dzia\u0142anie kart specjalnych",
              "Karty specjalne dzia\u0142aj\u0105 po zagraniu, tak\u017Ce wtedy, gdy nie wygrasz nimi lewy:",
              "- Walet odwraca si\u0142\u0119 kart ju\u017C w lewie, w kt\u00F3rej zosta\u0142 zagrany. Dw\u00F3jka staje si\u0119 wtedy najsilniejsza, a as najs\u0142abszy. Ten porz\u0105dek obowi\u0105zuje do nast\u0119pnego odwr\u00F3cenia. Walety w tej samej lewie znosz\u0105 si\u0119 parami: dwa niczego nie zmieniaj\u0105, trzy odwracaj\u0105 kolejno\u015B\u0107 raz.",
              "- Po zagraniu damy w nast\u0119pnej lewie mo\u017Cesz wybra\u0107 kart\u0119 jako ostatni, znaj\u0105c decyzje przeciwnik\u00F3w. Poczekaj, a\u017C dokonaj\u0105 wyboru, naci\u015Bnij C, \u017Ceby odczyta\u0107 ich karty, i wtedy wybierz swoj\u0105 strza\u0142kami oraz Enterem. Je\u015Bli w jednej lewie pojawi\u0105 si\u0119 przynajmniej dwie damy, nikt nie otrzyma tego przywileju.",
              "- Tr\u00F3jka pozwala w nast\u0119pnej lewie nacisn\u0105\u0107 C i pozna\u0107 liczb\u0119 kart w r\u0119kach przeciwnik\u00F3w. Zwyk\u0142e E podaje tylko \u0142\u0105czn\u0105 liczb\u0119 kart, z uwzgl\u0119dnieniem tych ju\u017C zdobytych.",
              "- \u00D3semka daje na nast\u0119pn\u0105 lew\u0119 mo\u017Cliwo\u015B\u0107 wymiany ca\u0142ej r\u0119ki na swoje zdobycze. Naci\u015Bnij C przed wyborem karty, je\u015Bli chcesz dokona\u0107 zamiany. Mo\u017Cesz te\u017C zachowa\u0107 obecn\u0105 r\u0119k\u0119. Do zamiany potrzebujesz przynajmniej jednej zdobytej karty.",
              "Klawiszem R sprawdzisz, czy wygrywaj\u0105 teraz niskie, czy wysokie karty, oraz jakiej mocy mo\u017Cesz u\u017Cy\u0107."),
            rule_section(:joker, "Joker",
              "Joker zmienia rozstrzygni\u0119cie lewy zale\u017Cnie od kart przeciwnik\u00F3w:",
              "- Je\u015Bli pozosta\u0142e karty da\u0142yby remis na najwy\u017Cszej warto\u015Bci, jeden joker przerywa wojn\u0119. Wszystkie karty zbiera gracz, kt\u00F3ry go wybra\u0142.",
              "- Je\u017Celi pozosta\u0142e karty wskazuj\u0105 jednego zwyci\u0119zc\u0119, jeden joker odbiera mu wygran\u0105 i wywo\u0142uje wojn\u0119. Karty pozostaj\u0105 do nast\u0119pnej lewy.",
              "- Dwa lub wi\u0119cej joker\u00F3w znosz\u0105 swoje dzia\u0142anie. O wyniku decyduj\u0105 wtedy pozosta\u0142e karty."),
            rule_section(:ending, "Koniec gry",
              "Wygrywasz, gdy jako jedyny masz jeszcze karty. Gdy wojna wyczerpie karty wszystkich graczy, nikt nie mo\u017Ce jej doko\u0144czy\u0107 i jest remis.",
              "Gra ko\u0144czy si\u0119 r\u00F3wnie\u017C po 50 lewach. Wtedy por\u00F3wnuje si\u0119 wszystkie posiadane karty, zar\u00F3wno w r\u0119kach, jak i w\u015Br\u00F3d zdobyczy. Wygrywa osoba z najwi\u0119ksz\u0105 liczb\u0105 kart; przy r\u00F3wnych najwy\u017Cszych wynikach jest remis."),
            rule_section(:variants, "Limit lew",
              "Przed gr\u0105 mo\u017Cesz ustali\u0107 w ustawieniach sto\u0142u inny limit: od 20 do 100 lew. Spos\u00F3b wy\u0142aniania zwyci\u0119zcy po jego osi\u0105gni\u0119ciu pozostaje taki sam."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: wybierz kart\u0119 w r\u0119ce.",
              "Enter: zagraj wybran\u0105 kart\u0119.",
              "Z: przejd\u017A do nast\u0119pnej karty w r\u0119ce; je\u015Bli to twoja jedyna karta, zagraj j\u0105.",
              "Shift+Z: przejd\u017A do poprzedniej karty w r\u0119ce; je\u015Bli to twoja jedyna karta, zagraj j\u0105.",
              "C: u\u017Cyj mocy karty: po damie odczytaj cudze wybory, po tr\u00F3jce sprawd\u017A liczby kart w r\u0119kach, a po \u00F3semce zamie\u0144 r\u0119k\u0119 ze stosem.",
              "E: odczytaj, ile kart ma \u0142\u0105cznie ka\u017Cdy gracz.",
              "T: odczytaj, kto ju\u017C wybra\u0142 kart\u0119.",
              "R: odczytaj bie\u017C\u0105cy porz\u0105dek kart i dost\u0119pne moce.",
              "V: odczytaj wynik ostatniej lewy.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u00AB\u041D\u0430\u0443\u0447\u043D\u043E\u0439 \u0432\u043E\u0439\u043D\u0435\u00BB \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432 \u0432\u0441\u0435 \u043A\u0430\u0440\u0442\u044B. \u0417\u0434\u0435\u0441\u044C \u0432\u044B \u0441\u0430\u043C\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0435, \u0447\u0435\u043C \u0445\u043E\u0434\u0438\u0442\u044C, \u0430 \u043E\u0441\u043E\u0431\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u0441\u0445\u043E\u0434 \u0441\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u0438\u043B\u0438 \u0434\u0430\u0442\u044C \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u043D\u0430 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u0445\u043E\u0434\u0443.",
              "\u0418\u0433\u0440\u0430\u044E\u0442 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0432\u043E\u0441\u044C\u043C\u0438 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0433\u043E \u043D\u0430\u0431\u043E\u0440\u0430: \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u043E\u0442 \u0434\u0432\u043E\u0439\u043A\u0438 \u0434\u043E \u0442\u0443\u0437\u0430 \u0438 \u043E\u0434\u0438\u043D \u0434\u0436\u043E\u043A\u0435\u0440. \u041C\u0430\u0441\u0442\u044C \u043D\u0430 \u0441\u0438\u043B\u0443 \u043A\u0430\u0440\u0442\u044B \u043D\u0435 \u0432\u043B\u0438\u044F\u0435\u0442."),
            rule_section(:play, "\u0412\u044B\u0431\u043E\u0440 \u043A\u0430\u0440\u0442\u044B \u0438 \u0432\u0437\u044F\u0442\u043A\u0430",
              "\u0418\u0433\u0440\u043E\u043A\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043A\u0430\u0440\u0442\u044B \u0442\u0430\u0439\u043D\u043E \u0434\u0440\u0443\u0433 \u043E\u0442 \u0434\u0440\u0443\u0433\u0430. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u043D\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 T \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442, \u043A\u0442\u043E \u0443\u0436\u0435 \u0441\u0434\u0435\u043B\u0430\u043B \u0432\u044B\u0431\u043E\u0440. \u041A\u043E\u0433\u0434\u0430 \u0433\u043E\u0442\u043E\u0432\u044B \u0432\u0441\u0435, \u043A\u0430\u0440\u0442\u044B \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
              "\u041A\u0430\u0436\u0434\u043E\u0435 \u0442\u0430\u043A\u043E\u0435 \u0441\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u0432\u0437\u044F\u0442\u043A\u043E\u0439. \u0412\u0441\u0435 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u043F\u043E\u043B\u043E\u0436\u0438\u043B \u0441\u0430\u043C\u0443\u044E \u0441\u0442\u0430\u0440\u0448\u0443\u044E. \u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043E\u0442 \u043C\u043B\u0430\u0434\u0448\u0435\u0439 \u043A \u0441\u0442\u0430\u0440\u0448\u0435\u0439: \u0434\u0432\u043E\u0439\u043A\u0430, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438, \u0432\u0430\u043B\u0435\u0442, \u0434\u0430\u043C\u0430, \u043A\u043E\u0440\u043E\u043B\u044C, \u0442\u0443\u0437. \u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 V.",
              "\u0412\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u043F\u043E\u043A\u0430 \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0442 \u0440\u0443\u043A\u0438. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0443\u0436\u043D\u043E \u0440\u0430\u0437\u044B\u0433\u0440\u0430\u0442\u044C \u0432\u0441\u0435 \u043A\u0430\u0440\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0443\u0436\u0435 \u0431\u044B\u043B\u0438 \u0443 \u0432\u0430\u0441, \u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u0442\u0435\u043C \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u043D\u0430 \u0440\u0443\u043A\u0438 \u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u043D\u0443\u044E \u0441\u0442\u043E\u043F\u043A\u0443. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442 \u043D\u0438 \u043A\u0430\u0440\u0442 \u0432 \u0440\u0443\u043A\u0435, \u043D\u0438 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442, \u0432\u044B \u0432\u044B\u0431\u044B\u0432\u0430\u0435\u0442\u0435."),
            rule_section(:war, "\u0412\u043E\u0439\u043D\u0430 \u043F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043A\u0430\u0440\u0442",
              "\u0415\u0441\u043B\u0438 \u0441\u0442\u0430\u0440\u0448\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0441\u044B\u0433\u0440\u0430\u043B\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A, \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0432\u043E\u0439\u043D\u0430. \u041F\u043E\u043A\u0430 \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u044B, \u0430 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0432 \u0438\u0433\u0440\u0435 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0435\u0449\u0451 \u043F\u043E \u043E\u0434\u043D\u043E\u0439. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0438\u0442 \u0438 \u043A\u0430\u0440\u0442\u044B, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043D\u0438\u0447\u044C\u0435\u0439.",
              "\u0412\u043E\u0439\u043D\u0430 \u043C\u043E\u0436\u0435\u0442 \u0434\u043B\u0438\u0442\u044C\u0441\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u0437\u044F\u0442\u043E\u043A. \u041A\u0430\u0436\u0434\u0430\u044F \u043D\u043E\u0432\u0430\u044F \u043D\u0438\u0447\u044C\u044F \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u043E\u043F\u043A\u0443, \u043F\u043E\u043A\u0430 \u0435\u0451 \u043D\u0435 \u0437\u0430\u0431\u0435\u0440\u0451\u0442 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C."),
            rule_section(:powers, "\u041E\u0441\u043E\u0431\u044B\u0435 \u043A\u0430\u0440\u0442\u044B",
              "\u041E\u0441\u043E\u0431\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u043A\u0430\u0440\u0442\u044B, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0441\u0430\u043C\u0430 \u043A\u0430\u0440\u0442\u0430 \u043D\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0430 \u0432\u0437\u044F\u0442\u043A\u0443:",
              "- \u0412\u0430\u043B\u0435\u0442 \u043C\u0435\u043D\u044F\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u043D\u0441\u0442\u0432\u043E \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u043E\u0435 \u0443\u0436\u0435 \u0432 \u0442\u043E\u0439 \u0432\u0437\u044F\u0442\u043A\u0435, \u0433\u0434\u0435 \u043E\u043D \u0441\u044B\u0433\u0440\u0430\u043D. \u0422\u0435\u043F\u0435\u0440\u044C \u0434\u0432\u043E\u0439\u043A\u0430 \u0441\u0430\u043C\u0430\u044F \u0441\u0438\u043B\u044C\u043D\u0430\u044F, \u0430 \u0442\u0443\u0437 \u0441\u0430\u043C\u044B\u0439 \u0441\u043B\u0430\u0431\u044B\u0439; \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0434\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u043E\u0442\u0430. \u0412\u0430\u043B\u0435\u0442\u044B \u0432 \u043E\u0434\u043D\u043E\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430 \u043F\u043E\u043F\u0430\u0440\u043D\u043E: \u0434\u0432\u0430 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442 \u043D\u0438\u0447\u0435\u0433\u043E, \u0442\u0440\u0438 \u043F\u0435\u0440\u0435\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u044E\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043E\u0434\u0438\u043D \u0440\u0430\u0437.",
              "- \u0414\u0430\u043C\u0430 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u043C, \u0437\u043D\u0430\u044F \u0447\u0443\u0436\u0438\u0435 \u043A\u0430\u0440\u0442\u044B. \u0414\u043E\u0436\u0434\u0438\u0442\u0435\u0441\u044C \u0432\u044B\u0431\u043E\u0440\u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 C, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0438\u0445 \u043A\u0430\u0440\u0442\u044B, \u0437\u0430\u0442\u0435\u043C \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043E\u044E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter. \u0415\u0441\u043B\u0438 \u0432 \u043E\u0434\u043D\u043E\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u0441\u044B\u0433\u0440\u0430\u043D\u044B \u0445\u043E\u0442\u044F \u0431\u044B \u0434\u0432\u0435 \u0434\u0430\u043C\u044B, \u044D\u0442\u043E \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043D\u0438\u043A\u0442\u043E.",
              "- \u0422\u0440\u043E\u0439\u043A\u0430 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u043D\u0430\u0436\u0430\u0442\u044C C \u0438 \u0443\u0437\u043D\u0430\u0442\u044C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u0432 \u0440\u0443\u043A\u0430\u0445 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0430 E \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0431\u0449\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u043A\u0430\u0440\u0442, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0443\u0436\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435.",
              "- \u0412\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0430 \u0434\u0430\u0451\u0442 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u043F\u0440\u0430\u0432\u043E \u043E\u0431\u043C\u0435\u043D\u044F\u0442\u044C \u0432\u0441\u044E \u0440\u0443\u043A\u0443 \u043D\u0430 \u0441\u0432\u043E\u044E \u0441\u0442\u043E\u043F\u043A\u0443 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442. \u0415\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u043E\u0431\u043C\u0435\u043D\u044F\u0442\u044C\u0441\u044F, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 C \u0434\u043E \u0432\u044B\u0431\u043E\u0440\u0430 \u043A\u0430\u0440\u0442\u044B. \u041C\u043E\u0436\u043D\u043E \u0438 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0440\u0443\u043A\u0443 \u043A\u0430\u043A \u0435\u0441\u0442\u044C. \u0414\u043B\u044F \u043E\u0431\u043C\u0435\u043D\u0430 \u043D\u0443\u0436\u043D\u0430 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u0430 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 R \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442, \u043A\u0430\u043A\u0438\u0435 \u043A\u0430\u0440\u0442\u044B \u0441\u0435\u0439\u0447\u0430\u0441 \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u2014 \u043C\u043B\u0430\u0434\u0448\u0438\u0435 \u0438\u043B\u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u2014 \u0438 \u043A\u0430\u043A\u043E\u0435 \u043E\u0441\u043E\u0431\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432\u0430\u043C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E."),
            rule_section(:joker, "\u0414\u0436\u043E\u043A\u0435\u0440",
              "\u0414\u0436\u043E\u043A\u0435\u0440 \u043C\u0435\u043D\u044F\u0435\u0442 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E\u0441\u0442\u0438 \u043E\u0442 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442:",
              "- \u0415\u0441\u043B\u0438 \u0431\u0435\u0437 \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u0441\u0430\u043C\u044B\u0435 \u0441\u0438\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0434\u0430\u043B\u0438 \u0431\u044B \u043D\u0438\u0447\u044C\u044E, \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0434\u0436\u043E\u043A\u0435\u0440 \u043F\u0440\u0435\u043A\u0440\u0430\u0449\u0430\u0435\u0442 \u0432\u043E\u0439\u043D\u0443 \u0438 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u044E \u0432\u0437\u044F\u0442\u043A\u0443 \u0441\u0432\u043E\u0435\u043C\u0443 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0443.",
              "- \u0415\u0441\u043B\u0438 \u0431\u0435\u0437 \u0434\u0436\u043E\u043A\u0435\u0440\u0430 \u0431\u044B\u043B \u0431\u044B \u043E\u0434\u0438\u043D \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C, \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0434\u0436\u043E\u043A\u0435\u0440 \u043B\u0438\u0448\u0430\u0435\u0442 \u0435\u0433\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0432\u043E\u0439\u043D\u0443. \u041A\u0430\u0440\u0442\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0434\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438.",
              "- \u0414\u0432\u0430 \u0438 \u0431\u043E\u043B\u0435\u0435 \u0434\u0436\u043E\u043A\u0435\u0440\u043E\u0432 \u043E\u0442\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430. \u0422\u043E\u0433\u0434\u0430 \u0438\u0441\u0445\u043E\u0434 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B."),
            rule_section(:ending, "\u041A\u043E\u043D\u0435\u0446 \u0438\u0433\u0440\u044B",
              "\u041E\u0441\u0442\u0430\u0432\u0448\u0438\u0441\u044C \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u0438\u0433\u0440\u043E\u043A\u043E\u043C \u0441 \u043A\u0430\u0440\u0442\u0430\u043C\u0438, \u0432\u044B \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442\u0435. \u0415\u0441\u043B\u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u043E\u0439\u043D\u044B \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u043B\u0438\u0441\u044C \u0443 \u0432\u0441\u0435\u0445 \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043D\u0435\u043A\u043E\u043C\u0443, \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u044F.",
              "\u0422\u0430\u043A\u0436\u0435 \u043F\u0430\u0440\u0442\u0438\u044F \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 50 \u0432\u0437\u044F\u0442\u043E\u043A. \u0422\u043E\u0433\u0434\u0430 \u0441\u0447\u0438\u0442\u0430\u044E\u0442 \u0432\u0441\u0435 \u043A\u0430\u0440\u0442\u044B \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u2014 \u0438 \u0432 \u0440\u0443\u043A\u0435, \u0438 \u0432 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u043E\u0439 \u0441\u0442\u043E\u043F\u043A\u0435. \u0423 \u043A\u043E\u0433\u043E \u0438\u0445 \u0431\u043E\u043B\u044C\u0448\u0435 \u0432\u0441\u0435\u0433\u043E, \u0442\u043E\u0442 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442; \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u043E \u043B\u0443\u0447\u0448\u0438\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043D\u0438\u0447\u044C\u044E."),
            rule_section(:variants, "\u041B\u0438\u043C\u0438\u0442 \u0432\u0437\u044F\u0442\u043E\u043A",
              "\u041F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0434\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0439 \u043F\u0440\u0435\u0434\u0435\u043B \u2014 \u043E\u0442 20 \u0434\u043E 100 \u0432\u0437\u044F\u0442\u043E\u043A. \u041F\u043E \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 \u043B\u0438\u043C\u0438\u0442\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0442\u0435\u043C \u0436\u0435 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u043E\u043C \u043A\u0430\u0440\u0442."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0432 \u0440\u0443\u043A\u0435.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "Z: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u0435; \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432 \u0440\u0443\u043A\u0435 \u2014 \u0441\u0440\u0430\u0437\u0443 \u0441\u044B\u0433\u0440\u0430\u0442\u044C.",
              "Shift+Z: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u0435; \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u0432 \u0440\u0443\u043A\u0435 \u2014 \u0441\u0440\u0430\u0437\u0443 \u0441\u044B\u0433\u0440\u0430\u0442\u044C.",
              "C: \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043E\u0441\u043E\u0431\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u2014 \u043F\u043E\u0441\u043B\u0435 \u0434\u0430\u043C\u044B \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0447\u0443\u0436\u0438\u0435 \u043A\u0430\u0440\u0442\u044B, \u043F\u043E\u0441\u043B\u0435 \u0442\u0440\u043E\u0439\u043A\u0438 \u0443\u0437\u043D\u0430\u0442\u044C \u0440\u0430\u0437\u043C\u0435\u0440 \u0447\u0443\u0436\u0438\u0445 \u0440\u0443\u043A, \u043F\u043E\u0441\u043B\u0435 \u0432\u043E\u0441\u044C\u043C\u0451\u0440\u043A\u0438 \u043E\u0431\u043C\u0435\u043D\u044F\u0442\u044C \u0440\u0443\u043A\u0443 \u0441\u043E \u0441\u0432\u043E\u0435\u0439 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u043E\u0439 \u0441\u0442\u043E\u043F\u043A\u043E\u0439.",
              "E: \u0443\u0437\u043D\u0430\u0442\u044C \u043E\u0431\u0449\u0435\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u043A\u0442\u043E \u0443\u0436\u0435 \u0432\u044B\u0431\u0440\u0430\u043B \u043A\u0430\u0440\u0442\u0443.",
              "R: \u0443\u0437\u043D\u0430\u0442\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0435 \u0441\u0442\u0430\u0440\u0448\u0438\u043D\u0441\u0442\u0432\u043E \u043A\u0430\u0440\u0442 \u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u043E\u0441\u043E\u0431\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F.",
              "V: \u0443\u0437\u043D\u0430\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438.")
          ]
        end
      end
